package easy;public class NQueens{public static java.util.List<java.util.List<String>>solveNQueens(int n){java.util.List<java.util.List<String>>r=new java.util.ArrayList<>();int[]q=new int[n];solve(r,q,0,n);return r;}static void solve(java.util.List<java.util.List<String>>r,int[]q,int row,int n){if(row==n){java.util.List<String>b=new java.util.ArrayList<>();for(int i=0;i<n;i++){char[]c=new char[n];java.util.Arrays.fill(c,'.');c[q[i]]=85;b.add(new String(c));}r.add(b);return;}for(int c=0;c<n;c++){if(isSafe(q,row,c)){q[row]=c;solve(r,q,row+1,n);}}}static boolean isSafe(int[]q,int r,int c){for(int i=0;i<r;i++){if(q[i]==c||Math.abs(q[i]-c)==Math.abs(i-r))return false;}return true;}public static void main(String[]args){System.out.println("N-Queens works\n");}}
